/* is_empty • returns the line length when it is empty, 0 otherwise */
static size_t
is_empty(const uint8_t *data, size_t size)
{
        size_t i;

        for (i = 0; i < size && data[i] != '\n'; i++)
                if (data[i] != ' ')
                        return 0;

        return i + 1;
}

